import type React from "react";

export type TimeFormat = "12" | "24";

export interface TimeValue {
  hours: number;
  minutes: number;
  period?: "AM" | "PM";
}

export interface TimePickerProps {
  value?: TimeValue;
  defaultValue?: TimeValue;
  onChange?: (value: TimeValue) => void;
  format?: TimeFormat;
  minuteStep?: number;
  placeholder?: string;
  disabled?: boolean;
  className?: string;
  style?: React.CSSProperties;
}

﻿"use client";

import { useEffect, useId, useRef, useState } from "react";

import { cn } from "@/lib/utils";

import type { TimePickerProps, TimeValue } from "./time-picker.types";

function pad(n: number) {
  return String(n).padStart(2, "0");
}

function fmt(v: TimeValue, format: string) {
  if (!v) return "";
  if (format === "12") {
    const h12 = v.hours % 12 || 12;
    return `${pad(h12)}:${pad(v.minutes)} ${v.period ?? "AM"}`;
  }
  return `${pad(v.hours)}:${pad(v.minutes)}`;
}

export function TimePicker({
  value: controlled,
  defaultValue,
  onChange,
  format = "24",
  minuteStep = 5,
  placeholder = "Select time",
  disabled = false,
  className,
  style,
}: TimePickerProps) {
  const [internal, setInternal] = useState<TimeValue>(defaultValue ?? { hours: 0, minutes: 0, period: "AM" });
  // achado real: isEmpty comparava hours===0 && minutes===0, então selecionar meia-noite
  // (00:00) de propósito ficava indistinguível de "nada selecionado ainda" e o placeholder
  // continuava exibido pra sempre nesse caso, mesmo depois do clique do usuário registrar
  // corretamente (onChange disparava certo, só o texto exibido mentia). `touched` rastreia
  // interação real, independente de qual valor foi escolhido
  const [touched, setTouched] = useState(false);
  const [open, setOpen] = useState(false);
  const isControlled = controlled !== undefined;
  const val = isControlled ? controlled! : internal;
  const rootRef = useRef<HTMLDivElement>(null);
  const popoverId = useId();

  const hours =
    format === "12"
      ? Array.from({ length: 12 }, (_, i) => (i === 0 ? 12 : i))
      : Array.from({ length: 24 }, (_, i) => i);
  const minutes = Array.from({ length: Math.ceil(60 / minuteStep) }, (_, i) => i * minuteStep);

  const update = (next: Partial<TimeValue>) => {
    const merged = { ...val, ...next };
    if (!isControlled) setInternal(merged);
    setTouched(true);
    onChange?.(merged);
  };

  useEffect(() => {
    const handler = (e: MouseEvent) => {
      if (!rootRef.current?.contains(e.target as Node)) setOpen(false);
    };
    // achado real: popover fechava clicando fora, mas não tinha Escape nenhum — mesmo
    // padrão já corrigido no NavigationMenu (todo outro widget flutuante da lib fecha com Escape)
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") setOpen(false);
    };
    document.addEventListener("mousedown", handler);
    document.addEventListener("keydown", onKey);
    return () => {
      document.removeEventListener("mousedown", handler);
      document.removeEventListener("keydown", onKey);
    };
  }, []);

  const displayH = format === "12" ? val.hours % 12 || 12 : val.hours;
  const isEmpty = isControlled ? false : !defaultValue && !touched;

  return (
    <div ref={rootRef} className={cn("relative inline-block", className)} style={style}>
      <button
        type="button"
        aria-haspopup="dialog"
        aria-expanded={open}
        aria-controls={open ? popoverId : undefined}
        onClick={() => !disabled && setOpen((o) => !o)}
        disabled={disabled}
        className={cn(
          "flex items-center gap-(--spacing-sm) px-(--spacing-md) py-(--spacing-sm) rounded-(--radius-sm) border text-body-callout min-w-[140px]",
          "transition-colors duration-150",
          open ? "border-patina bg-raised" : "border-rule bg-canvas hover:border-patina/50",
          disabled && "opacity-50 cursor-not-allowed"
        )}
      >
        {/* emoji como ícone: desaconselhado em produção, sugestão de melhoria (não bloqueante) */}
        <span aria-hidden="true">🕐</span>
        <span className={isEmpty ? "text-faint" : "text-foreground"}>{isEmpty ? placeholder : fmt(val, format)}</span>
      </button>

      {open && (
        <div
          id={popoverId}
          role="dialog"
          aria-label="Choose time"
          className="absolute top-full mt-(--spacing-2xs) left-0 z-50 bg-raised border border-rule rounded-(--radius-md) shadow-[0_8px_32px_-8px_oklch(0%_0_0/0.45),0_2px_8px_-2px_oklch(0%_0_0/0.28)] flex items-stretch overflow-hidden animate-in fade-in slide-in-from-top-1 duration-100"
        >
          {/* Hours */}
          <div className="flex flex-col">
            {/* text-[0.625rem]: below scale minimum, micro-label de coluna */}
            <div className="text-[0.625rem] font-bold text-faint uppercase tracking-widest px-(--spacing-md) py-(--spacing-xs) border-b border-rule">
              Hour
            </div>
            <div className="overflow-y-auto max-h-44 py-(--spacing-2xs)">
              {hours.map((h) => (
                <button
                  key={h}
                  type="button"
                  aria-pressed={displayH === h}
                  onClick={() => {
                    const newH =
                      format === "12"
                        ? h === 12
                          ? val.period === "PM"
                            ? 12
                            : 0
                          : h + (val.period === "PM" ? 12 : 0)
                        : h;
                    update({ hours: newH });
                  }}
                  className={cn(
                    "block w-full px-(--spacing-lg) py-(--spacing-2xs) text-center text-body-callout hover:bg-graphite transition-colors",
                    displayH === h ? "bg-patina text-patina-fg font-bold" : "text-foreground"
                  )}
                >
                  {pad(h)}
                </button>
              ))}
            </div>
          </div>

          <div className="flex items-center px-(--spacing-2xs) text-muted font-bold">:</div>

          {/* Minutes */}
          <div className="flex flex-col">
            {/* text-[0.625rem]: below scale minimum, micro-label de coluna */}
            <div className="text-[0.625rem] font-bold text-faint uppercase tracking-widest px-(--spacing-md) py-(--spacing-xs) border-b border-rule">
              Min
            </div>
            <div className="overflow-y-auto max-h-44 py-(--spacing-2xs)">
              {minutes.map((m) => (
                <button
                  key={m}
                  type="button"
                  aria-pressed={val.minutes === m}
                  onClick={() => update({ minutes: m })}
                  className={cn(
                    "block w-full px-(--spacing-lg) py-(--spacing-2xs) text-center text-body-callout hover:bg-graphite transition-colors",
                    val.minutes === m ? "bg-patina text-patina-fg font-bold" : "text-foreground"
                  )}
                >
                  {pad(m)}
                </button>
              ))}
            </div>
          </div>

          {/* AM/PM */}
          {format === "12" && (
            <div className="flex flex-col border-l border-rule">
              {/* text-[0.625rem]: below scale minimum, micro-label de coluna */}
              <div className="text-[0.625rem] font-bold text-faint uppercase tracking-widest px-(--spacing-md) py-(--spacing-xs) border-b border-rule">
                Period
              </div>
              <div className="flex flex-col gap-(--spacing-2xs) p-(--spacing-sm)">
                {(["AM", "PM"] as const).map((p) => (
                  <button
                    key={p}
                    type="button"
                    aria-pressed={val.period === p}
                    onClick={() => update({ period: p })}
                    className={cn(
                      "px-(--spacing-md) py-(--spacing-2xs) rounded-(--radius-sm) text-body-callout font-medium transition-colors",
                      val.period === p ? "bg-patina text-patina-fg" : "text-foreground hover:bg-graphite"
                    )}
                  >
                    {p}
                  </button>
                ))}
              </div>
            </div>
          )}
        </div>
      )}
    </div>
  );
}
